installer-gui-script.script:
function whyfsArchCheck() {
    var appleSilicon = system.sysctl('hw.optional.arm64') == 1;
    if (appleSilicon != ('@ARCH@' == 'arm64')) {
        my.result.type = 'Fatal';
        my.result.title = 'This is the WhyFS package for another kind of Mac';
        my.result.message = 'Use the ' + (appleSilicon ? 'Apple silicon (arm64)' : 'Intel (x86_64)') + ' package.';
        return false;
    }
    return true;
}
